frappe.ui.form.on('Material Request', {
    refresh: function(frm) {

        if (!frm.doc.__islocal) return;

        // Check if any item row has production_plan filled
        let has_production_plan = false;

        (frm.doc.items || []).forEach(function(d) {
            if (d.production_plan) {
                has_production_plan = true;
            }
        });

        if (has_production_plan) {

            frm.set_value('material_request_type', 'Purchase');
            frm.set_df_property('material_request_type', 'read_only', 1);

            frm.fields_dict.material_request_type.df.options = ['Purchase'];
            frm.refresh_field('material_request_type');
        }
    }
});

