            .then(r => {
                console.log("res:",r);
                if (r && r.message && r.message.custom_section) {
                    frm.set_value("custom_section", r.message.custom_section);
                }
            });

  }
}

function set_source_wh_mandatory(frm) {

    const mandatory_types = [
        "Material Transfer",
       // "Material Issue",
       // "Material Transfer for Manufacture"
    ];

    const is_mandatory = mandatory_types.includes(frm.doc.stock_entry_type);

    frm.set_df_property(
        "from_warehouse",
        "reqd",
        is_mandatory
    );

    frm.refresh_field("from_warehouse");
}

