frappe.ui.form.on("Work Order", {
    refresh(frm) {
        calculate_main_production_qty(frm);
    },

    qty(frm) {
        calculate_main_production_qty(frm);
    },

    custom_sample_required(frm) {
        calculate_main_production_qty(frm);
    },

    custom_sample_qty(frm) {
        calculate_main_production_qty(frm);
    }
});


function calculate_main_production_qty(frm) {

    let produced_qty = flt(frm.doc.qty);
    let sample_qty = 0;

    if (frm.doc.custom_sample_required) {
        sample_qty = flt(frm.doc.custom_sample_qty);
    }

    if (sample_qty > produced_qty) {

        frappe.msgprint({
            title: __("Invalid Sample Quantity"),
            message: __("Sample Quantity cannot be greater than Work Order Quantity."),
            indicator: "red"
        });

        frm.set_value("custom_sample_qty", produced_qty);
        sample_qty = produced_qty;
    }

    let main_qty = produced_qty - sample_qty;

    frm.set_value("custom_main_production_qty", main_qty);
}

