});


function pull_bom_details(frm) {

    if (!frm.doc.bom_no) {
        return;
    }

    frappe.db.get_doc("BOM", frm.doc.bom_no).then(bom => {

        // BOM Default Target Warehouse
        if (bom.default_target_warehouse) {
            frm.set_value(
                "fg_warehouse",
                bom.default_target_warehouse
            );
        }

        // Sample Required
        if (bom.custom_sample_required !== undefined) {
            frm.set_value(
                "custom_sample_required",
                bom.custom_sample_required
            );
        }

        // Sample Quantity
        if (bom.custom_sample_qty !== undefined) {
            frm.set_value(
                "custom_sample_qty",
                bom.custom_sample_qty
            );
        }

        // Sample UOM
        if (bom.custom_sample_uom) {
            frm.set_value(
                "custom_sample_uom",
                bom.custom_sample_uom
            );
        }

        // Sample Warehouse
        // if (bom.custom_sample_warehouse) {
        //     frm.set_value(
        //         "custom_sample_warehouse",
        //         bom.custom_sample_warehouse
        //     );
        // }

        // Calculate main production quantity
        calculate_main_production_qty(frm);
    });
}


function calculate_main_production_qty(frm) {

    let production_qty = flt(frm.doc.qty);
    let sample_qty = 0;

    if (frm.doc.custom_sample_required) {
        sample_qty = flt(frm.doc.custom_sample_qty);
    }

    if (sample_qty > production_qty) {

        frappe.msgprint({
            title: __("Invalid Sample Quantity"),
            message: __("Sample Quantity cannot be greater than Production Quantity."),
            indicator: "red"
        });

        frm.set_value("custom_sample_qty", production_qty);
        sample_qty = production_qty;
    }

    let main_qty = production_qty - sample_qty;

    frm.set_value(
        "custom_main_production_qty",
        main_qty
    );
}

