function set_manufacturing_batch(frm) {

    if (frm.doc.work_order && !frm.doc.custom_manufacturing_batch) {

        frappe.db.get_value(
            "Work Order",
            frm.doc.work_order,
            "custom_manufacturing_batch",
            function (r) {

                if (r && r.custom_manufacturing_batch) {

                    frm.set_value(
                        "custom_manufacturing_batch",
                        r.custom_manufacturing_batch
                    );

                }

            }
        );

    }

