            let row = frm.add_child("container_code_details");

            row.container_no = code;  // random
            row.net_weight = net_weight;
            row.tare_weight = 5;
            row.gross_weight = net_weight + 5;
        }

        frm.refresh_field("container_code_details");
    }
});


