frappe.ui.form.on('Weekly Off Roster Detail', {

    // ==================================================
    // Employee selected
    // Branch / Department / Designation auto fill
    // ==================================================

    employee: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.employee) {
            return;
        }

        frappe.db.get_value(
            'Employee',
            row.employee,
            [
                'branch',
                'department',
                'designation'
            ],
            function(r) {

                if (r) {

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        'branch',
                        r.branch
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        'department',
                        r.department
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        'designation',
                        r.designation
                    );
                }
            }
        );
    },


    // ==================================================
    // Weekly Off Date selected
    // Day auto fill + Parent Date Range validation
    // ==================================================

    weekly_off_date: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.weekly_off_date) {
            return;
        }


        // ----------------------------------------------
        // Parent From Date / To Date check
        // ----------------------------------------------

        if (frm.doc.from_date && row.weekly_off_date < frm.doc.from_date) {

            frappe.msgprint({
                title: "Invalid Weekly Off Date",
                message:
                    "Weekly Off Date cannot be before From Date.<br><br>" +
                    "<b>From Date:</b> " + frm.doc.from_date,
                indicator: "red"
            });

            frappe.model.set_value(
                cdt,
                cdn,
                "weekly_off_date",
                ""
            );

            frappe.model.set_value(
                cdt,
                cdn,
                "weekly_off_day",
                ""
            );

            return;
        }


        if (frm.doc.to_date && row.weekly_off_date > frm.doc.to_date) {

            frappe.msgprint({
                title: "Invalid Weekly Off Date",
                message:
                    "Weekly Off Date cannot be after To Date.<br><br>" +
                    "<b>To Date:</b> " + frm.doc.to_date,
                indicator: "red"
            });

            frappe.model.set_value(
                cdt,
                cdn,
                "weekly_off_date",
                ""
            );

            frappe.model.set_value(
                cdt,
                cdn,
                "weekly_off_day",
                ""
            );

            return;
        }


        // ----------------------------------------------
        // Day Auto Fill
        // ----------------------------------------------

        let date_parts = row.weekly_off_date.split("-");

        let date = new Date(
            parseInt(date_parts[0]),
            parseInt(date_parts[1]) - 1,
            parseInt(date_parts[2])
        );

        let days = [
            "Sunday",
            "Monday",
            "Tuesday",
            "Wednesday",
            "Thursday",
            "Friday",
            "Saturday"
        ];

        let day = days[date.getDay()];

        frappe.model.set_value(
            cdt,
            cdn,
            "weekly_off_day",
            day
        );
    }
});

