frappe.ui.form.on('New And Existing Product Analysis Module', {

    setup(frm) {
        set_organization_filter(frm);
    },

    onload(frm) {
        set_organization_filter(frm);
        calculate_next_analysis_date(frm);
    },

    refresh(frm) {
        set_organization_filter(frm);
        calculate_next_analysis_date(frm);
    },

    organization_type(frm) {
        frm.set_value('organization_name', '');
        set_organization_filter(frm);
    },

    date(frm) {
        calculate_next_analysis_date(frm);
    }
});


function set_organization_filter(frm) {

    frm.set_query('organization_name', function() {

        if (frm.doc.organization_type === 'Prospect') {

            return {
                filters: {
                    organization_type: 'Prospect',
                    status: 'Prospect'
                }
            };

        }

        if (frm.doc.organization_type === 'Customer') {

            return {
                filters: {
                    organization_type: 'Customer',
                    status: 'Converted'
                }
            };

        }

        if (frm.doc.organization_type === 'All') {

            return {
                filters: [
                    ['Prospect', 'organization_type', 'in', ['Prospect', 'Customer']],
                    ['Prospect', 'status', 'in', ['Prospect', 'Converted']]
                ]
            };

        }

        return {};
    });
}


function calculate_next_analysis_date(frm) {

    if (!frm.doc.date) {
        frm.set_value('next_analysis_date', '');
        return;
    }

    let next_date = frappe.datetime.add_months(
        frm.doc.date,
        6
    );

    frm.set_value(
        'next_analysis_date',
        next_date
    );
}

