                    data-doctype="New And Existing Product Analysis Module"
                    style="
                        border: 1px solid #d1d8dd;
                        border-radius: 8px;
                        padding: 18px;
                        cursor: pointer;
                        background: white;
                        transition: 0.2s;
                    "
                >

