                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                    ">

                        <div>

                            <div style="
                                font-size: 14px;
                                color: #6b7280;
                                margin-bottom: 6px;
                            ">
                                Product Analysis
                            </div>

                            <div style="
                                font-size: 17px;
                                font-weight: 600;
                            ">
                                New & Existing Product Analysis
                            </div>

                        </div>

                        <div style="font-size: 22px;">
                            →
                        </div>

                    </div>

                </div>


                <!-- Sample Request -->
                <div
                    class="prospect-dashboard-card"
                    data-doctype="Sample Request"
                    style="
                        border: 1px solid #d1d8dd;
                        border-radius: 8px;
                        padding: 18px;
                        cursor: pointer;
                        background: white;
                        transition: 0.2s;
                    "
                >

                    <div style="
                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                    ">

                        <div>

                            <div style="
                                font-size: 14px;
                                color: #6b7280;
                                margin-bottom: 6px;
                            ">
                                Samples
                            </div>

                            <div style="
                                font-size: 17px;
                                font-weight: 600;
                            ">
                                Sample Request
                            </div>

                        </div>

                        <div style="font-size: 22px;">
                            →
                        </div>

                    </div>

                </div>


                <!-- Sample Sent -->
                <div
                    class="prospect-dashboard-card"
                    data-doctype="Sample Sent"
                    style="
                        border: 1px solid #d1d8dd;
                        border-radius: 8px;
                        padding: 18px;
                        cursor: pointer;
                        background: white;
                        transition: 0.2s;
                    "
                >

                    <div style="
                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                    ">

                        <div>

                            <div style="
                                font-size: 14px;
                                color: #6b7280;
                                margin-bottom: 6px;
                            ">
                                Samples
                            </div>

                            <div style="
                                font-size: 17px;
                                font-weight: 600;
                            ">
                                Sample Sent
                            </div>

                        </div>

                        <div style="font-size: 22px;">
                            →
                        </div>

                    </div>

                </div>

            </div>

        </div>
    `;


    frm.fields_dict.custom_dashboard_html.$wrapper.html(html);


    // Card click
    frm.fields_dict.custom_dashboard_html.$wrapper
        .find(".prospect-dashboard-card")
        .on("click", function () {

            let doctype = $(this).attr("data-doctype");

