frappe.ui.form.on('Section-Wise Production Capacity', {

    output_type(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row) {
            return;
        }

        if (row.output_type === 'Kg') {

            frappe.model.set_value(
                cdt,
                cdn,
                'vial_strength',
                0
            );

            frappe.model.set_value(
                cdt,
                cdn,
                'vial_strength_uom',
                ''
            );

            frappe.model.set_value(
                cdt,
                cdn,
                'vial_monthly_output_quantity',
                0
            );

        }

        else if (row.output_type === 'Vial') {

            frappe.model.set_value(
                cdt,
                cdn,
                'monthly_output_kg',
                0
            );
        }

        set_section_field_permissions(frm, cdt, cdn);
    },


    vial_strength(frm, cdt, cdn) {
        calculate_monthly_output_kg(frm, cdt, cdn);
    },


    vial_strength_uom(frm, cdt, cdn) {
        calculate_monthly_output_kg(frm, cdt, cdn);
    },


    vial_monthly_output_quantity(frm, cdt, cdn) {
        calculate_monthly_output_kg(frm, cdt, cdn);
    }

});


function set_section_field_permissions(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!row) {
        return;
    }

    let grid = frm.fields_dict
        .section_wise_production_capacity
        .grid;

    if (!grid) {
        return;
    }

    let grid_row = grid.get_row(row.name);

    if (!grid_row) {
        return;
    }


    if (row.output_type === 'Kg') {

        grid_row.toggle_editable(
            'monthly_output_kg',
            true
        );

        grid_row.toggle_editable(
            'vial_strength',
            false
        );

        grid_row.toggle_editable(
            'vial_strength_uom',
            false
        );

        grid_row.toggle_editable(
            'vial_monthly_output_quantity',
            false
        );

    }


    else if (row.output_type === 'Vial') {

        grid_row.toggle_editable(
            'monthly_output_kg',
            false
        );

        grid_row.toggle_editable(
            'vial_strength',
            true
        );

        grid_row.toggle_editable(
            'vial_strength_uom',
            true
        );

        grid_row.toggle_editable(
            'vial_monthly_output_quantity',
            true
        );
    }
}


function calculate_monthly_output_kg(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!row || row.output_type !== 'Vial') {
        return;
    }

    if (
        !row.vial_strength ||
        !row.vial_strength_uom ||
        !row.vial_monthly_output_quantity
    ) {

        frappe.model.set_value(
            cdt,
            cdn,
            'monthly_output_kg',
            0
        );

        return;
    }

    let total_kg = 0;

    if (row.vial_strength_uom === 'mg') {

        total_kg =
            (
                row.vial_strength *
                row.vial_monthly_output_quantity
            ) / 1000000;

    }

    else if (row.vial_strength_uom === 'g') {

        total_kg =
            (
                row.vial_strength *
                row.vial_monthly_output_quantity
            ) / 1000;

    }

    frappe.model.set_value(
        cdt,
        cdn,
        'monthly_output_kg',
        total_kg
    );
}

