frappe.ui.form.on('Item Wise Production Capacity', {

    periodicity(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row) {
            return;
        }

        if (row.periodicity === 'Once a Year') {

            set_item_month_editable(
                frm,
                cdt,
                cdn,
                true
            );

        }

        else {

            // Other periodicity → Month clear
            frappe.model.set_value(
                cdt,
                cdn,
                'month',
                ''
            );

            // Month read only
            set_item_month_editable(
                frm,
                cdt,
                cdn,
                false
            );
        }
    },


    form_render(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row) {
            return;
        }

        if (row.periodicity === 'Once a Year') {

            set_item_month_editable(
                frm,
                cdt,
                cdn,
                true
            );

        }

        else {

            set_item_month_editable(
                frm,
                cdt,
                cdn,
                false
            );
        }
    }

});


function set_item_month_editable(
    frm,
    cdt,
    cdn,
    editable
) {

    let grid = frm.fields_dict
        .item_wise_production_capacity
        .grid;

    if (!grid) {
        return;
    }

    let row = locals[cdt][cdn];

    if (!row) {
        return;
    }

    let grid_row = grid.get_row(row.name);

    if (!grid_row) {
        return;
    }

    grid_row.toggle_editable(
        'month',
        editable
    );
}

