frappe.ui.form.on('BOM', {
    refresh: function(frm) {
        if (!frm.__multi_bom_observer) {
            frm.__multi_bom_observer = true;

            const observer = new MutationObserver(() => {
                       console.log("AAAA-",cur_dialog);
                if (cur_dialog && cur_dialog.title === 'Work Order' && cur_dialog.fields_dict && cur_dialog.fields_dict.use_multi_level_bom)
                {
                    let field = cur_dialog.fields_dict.use_multi_level_bom;
                     console.log("XXXXX-", field);
                    if (!field.df.hidden) {
                        console.log("ZZZZ-", field);
                        cur_dialog.set_value('use_multi_level_bom', 0);
                        field.df.hidden = 1;
                        field.refresh();
                        console.log('Multi-Level BOM field hidden');
                    }
                }
            });

            observer.observe(document.body, { childList: true, subtree: true });
        }
    }
});
